import json
def nc(n):
    raise ValueError('bad '+n)
def nd(pairs):
    d={}
    for k,v in pairs:
        if k in d: raise ValueError('dup')
        d[k]=v
    return d
tests = ['{\"a\":1,\"a\":2}', 'NaN', '[1, Infinity]', '{\"a\":{\"b\":1,\"b\":2}}', '1e999', '[1,]', '', '   ', '{\"a\":1} ', '[{\"op\":\"true\"}]', '\"\\\\ud800\"']
for t in tests:
    try:
        r = json.loads(t, parse_constant=nc, object_pairs_hook=nd)
        print(repr(t), 'OK ->', repr(r)[:60])
    except Exception as e:
        print(repr(t), type(e).__name__)
"
